/**
 * Phase 8 — THE DEMO PROJECT, END TO END, THROUGH THE PRODUCT'S OWN ROUTES.
 *
 * "The Future of Artificial Intelligence" — six scenes, 20 s each, 120 s.
 *
 * The SCRIPT IS WRITTEN BY THE TEAM. There is no AI provider key on this machine,
 * so the app's script-generation step honestly answers "Provider Not Connected"
 * and the narration text below is team-authored source material, recorded as such
 * in the project's own description. Nothing in this file is generated by a model.
 *
 * The CLIPS ARE SELECTED BY KEYWORD SEARCH and do not illustrate their scenes.
 * Every clip is one the provider actually returned for that scene's query in the
 * `search` run that was read — `source` refuses an id that was not offered.
 *
 * Modes (every one of them drives the app the way a user does):
 *   create                      sign up / sign in the demo account, create the project
 *                               through POST /api/studio/magic-create, then author the
 *                               six scenes through PATCH /api/projects/:id/scenes/:sceneId
 *   search [out.json]           GET /api/media?sceneId=…&mediaType=video&count=20
 *   source <order> <externalId> POST /api/media/select + POST /api/media/ingest
 *   render                      POST /api/studio/render {action:"enqueue"} and wait
 *   table [in.json] [out.md]    the six-row provenance table read from the database
 *
 * Usage: bun scripts/fixtures/p8demo-project.ts <mode> [args]
 * Env:   P8D_BASE (default http://127.0.0.1:3100), P8D_EMAIL, P8D_PASSWORD,
 *        P8D_PROJECT (project id, or read from /tmp/p8demo_ids.json), P8D_PRESET
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { prisma } from "@/lib/db";

const BASE = process.env.P8D_BASE ?? "http://127.0.0.1:3100";
const EMAIL = process.env.P8D_EMAIL ?? "demo@cavs.test";
const PASSWORD = process.env.P8D_PASSWORD ?? "demo-password-2026";
const IDS_PATH = process.env.P8D_IDS ?? "/tmp/p8demo_ids.json";
const PRESET = process.env.P8D_PRESET ?? "youtube-1080p";
const COUNT = Number(process.env.P8D_COUNT ?? 20);

type Json = Record<string, unknown>;

/* ---------------------------------------------------------------- content --
 * THE SIX SCENES. Title, narration (text only — nothing speaks it) and the
 * visual prompt the sourcing query is built from. Team-written; see the header.
 */
const TITLE = "The Future of Artificial Intelligence";

const SCRIPT_NOTE =
  "DEMO PROJECT — HOW THIS WAS MADE. The script of this project was WRITTEN BY THE TEAM, not generated by an AI " +
  "model: no AI provider key is present on this machine, so the app's script-generation step answers " +
  "\"Provider Not Connected\" and the six narration lines below are team-authored source material. The six clips " +
  "were selected by KEYWORD SEARCH of a stock-footage provider (Pixabay) and are NOT illustrations of the scenes " +
  "they sit under: a keyword-matched clip may show something merely related to the words, and one of them may not " +
  "be the subject at all. The delivered file contains no narration, no music, no sound effects and no subtitles, " +
  "and nothing has been screened or cleared. Timeline: six scenes x 20 s = 120 s.";

const SCENES: Array<{ order: number; title: string; narration: string; visualPrompt: string }> = [
  {
    order: 1,
    title: "A model writes a paragraph",
    narration: "A decade ago, a machine that could finish a sentence was a research curiosity.",
    visualPrompt: "a person typing at a laptop in a dim room",
  },
  {
    order: 2,
    title: "The scale of the training",
    narration: "Then the models got bigger, and the data got wider, and something that looked like fluency appeared.",
    visualPrompt: "server racks in a data centre, blinking lights",
  },
  {
    order: 3,
    title: "More than words",
    narration: "Now the same systems read images, hear speech and watch video.",
    visualPrompt: "a camera lens close up, light through glass",
  },
  {
    order: 4,
    title: "Where it still breaks",
    narration: "And they still invent things with total confidence, which is the part nobody has solved.",
    visualPrompt: "a screen full of garbled text or static",
  },
  {
    order: 5,
    title: "Working with it, not instead of it",
    narration: "The useful version is not replacement. It is a fast, tireless assistant you have to check.",
    visualPrompt: "a person sketching on a tablet at a desk",
  },
  {
    order: 6,
    title: "What we choose",
    narration: "The future of artificial intelligence is not a date. It is a series of choices about who checks the work.",
    visualPrompt: "a city skyline at dusk, wide",
  },
];

const SCENE_SECONDS = 20;

/* ------------------------------------------------------------------ plumbing */
async function signIn(): Promise<string> {
  const res = await fetch(`${BASE}/api/auth/signin`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
  });
  if (!res.ok) throw new Error(`signin answered ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const cookie = (res.headers.getSetCookie?.() ?? []).map((c) => c.split(";")[0]).join("; ");
  if (!cookie) throw new Error("signin answered OK but set no session cookie");
  return cookie;
}

async function call(cookie: string, path: string, init: RequestInit = {}) {
  const res = await fetch(`${BASE}${path}`, {
    ...init,
    headers: { "content-type": "application/json", cookie, ...(init.headers ?? {}) },
  });
  const text = await res.text();
  let json: unknown = null;
  try {
    json = JSON.parse(text);
  } catch {
    /* keep raw text */
  }
  return { status: res.status, json: json as Json | null, text };
}

function projectId(): string {
  if (process.env.P8D_PROJECT) return process.env.P8D_PROJECT;
  if (!existsSync(IDS_PATH)) throw new Error(`no project id: run the "create" mode first (${IDS_PATH} missing)`);
  return (JSON.parse(readFileSync(IDS_PATH, "utf8")) as { projectId: string }).projectId;
}

/**
 * The project's scenes in SCRIPT ORDER. `Scene.order` is per-chapter (two scenes
 * in each of three chapters all carry orders 1 and 2), so the script position is
 * the chapter's order first, then the scene's — numbered 1..N here and used
 * everywhere instead of the raw per-chapter order.
 */
async function scenes(pid?: string) {
  const rows = await prisma.scene.findMany({
    where: { projectId: pid ?? projectId() },
    orderBy: [{ chapter: { order: "asc" } }, { order: "asc" }],
    select: {
      id: true,
      order: true,
      chapterId: true,
      title: true,
      visualPrompt: true,
      narration: true,
      durationSeconds: true,
      chapter: { select: { order: true } },
    },
  });
  if (rows.length === 0) throw new Error(`project ${projectId()} has no scenes`);
  return rows.map((r, i) => ({ ...r, position: i + 1 }));
}

/* ------------------------------------------------------------------- create */
async function create() {
  /* 1. the demo account, through the app's own sign-up route */
  let cookie = "";
  const signup = await fetch(`${BASE}/api/auth/signup`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD, name: "Demo account" }),
  });
  const signupBody = (await signup.text()).slice(0, 300);
  console.log(`signup  → ${signup.status} ${signupBody.replace(/\s+/g, " ").slice(0, 160)}`);
  if (signup.status === 201 || signup.status === 200) {
    const c = (signup.headers.getSetCookie?.() ?? []).map((x) => x.split(";")[0]).join("; ");
    if (c) cookie = c;
  }
  if (!cookie) {
    cookie = await signIn();
    console.log(`signin  → 200 (account already existed)`);
  }
  const me = await call(cookie, "/api/auth/session");
  console.log(`session → ${me.status} ${JSON.stringify(me.json).slice(0, 200)}`);

  /* 2. the project, through the Create Video wizard's own route.
   *    The AI script step is attempted and honestly answers "Provider Not Connected";
   *    the deterministic steps persist Project + Chapter + Scene rows first.
   *    With P8D_PROJECT set the project already exists and only the authoring
   *    steps below run (used to re-author after a partial run). */
  let pid = process.env.P8D_PROJECT ?? "";
  if (pid) {
    console.log(`\nmagic-create  : skipped — authoring existing project ${pid}`);
  } else {
    const sourceText = SCENES.map((s) => s.narration).join(" ");
    const created = await call(cookie, "/api/studio/magic-create", {
      method: "POST",
      body: JSON.stringify({
        inputType: "SCRIPT",
        sourceText,
        format: "LONG",
        durationSeconds: 120,
        style: "cinematic",
        language: "en",
        voice: "documentary-warm",
        title: TITLE,
      }),
    });
    if (created.status !== 200) throw new Error(`magic-create answered ${created.status}: ${created.text.slice(0, 800)}`);
    const body = created.json as Json;
    const project = (body.project ?? {}) as Json;
    pid = String(project.id ?? "");
    if (!pid) throw new Error(`magic-create answered 200 but no project id: ${created.text.slice(0, 600)}`);
    console.log(`\nmagic-create → ${created.status}`);
    console.log(`  project      : ${pid}  "${String(project.title ?? "")}"`);
    console.log(`  blocked      : ${JSON.stringify(body.blocked)}`);
    const steps = (body.steps as Array<{ id: string; status: string; detail?: string }>) ?? [];
    for (const s of steps) console.log(`  step ${s.id.padEnd(10)} ${s.status}  ${(s.detail ?? "").slice(0, 120)}`);
  }

  /* 3. the description, through PATCH /api/projects/:id — the honesty record */
  const patched = await call(cookie, `/api/projects/${pid}`, {
    method: "PATCH",
    body: JSON.stringify({
      project: { title: TITLE, description: SCRIPT_NOTE, targetDurationSeconds: 120, targetAspectRatio: "SIXTEEN_NINE" },
    }),
  });
  if (patched.status !== 200) throw new Error(`project PATCH answered ${patched.status}: ${patched.text.slice(0, 500)}`);
  console.log(`project PATCH → ${patched.status} (description written, ${SCRIPT_NOTE.length} chars)`);

  /* 4. the six scenes: title, narration and duration through the scene route */
  const rows = await scenes(pid);
  console.log(`\nscenes on the project: ${rows.length}`);
  if (rows.length !== SCENES.length) {
    throw new Error(`the plan produced ${rows.length} scene(s); this demo needs exactly ${SCENES.length}`);
  }
  for (const row of rows) {
    const spec = SCENES.find((s) => s.order === row.position);
    if (!spec) throw new Error(`no script line for script position ${row.position}`);
    const r = await call(cookie, `/api/projects/${pid}/scenes/${row.id}`, {
      method: "PATCH",
      body: JSON.stringify({ title: spec.title, narration: spec.narration, durationSeconds: SCENE_SECONDS }),
    });
    if (r.status !== 200) throw new Error(`scene ${row.position} PATCH answered ${r.status}: ${r.text.slice(0, 500)}`);
    console.log(`  scene #${row.position} ${row.id} → ${r.status}  "${spec.title}"  ${SCENE_SECONDS} s`);
  }

  /* 5. the visual prompt — the sourcing hint the semantic query is built from.
   *    The product's scene PATCH accepts narration, title and duration only, so the
   *    prompt is written to the Scene row here. Reported as a gap, not hidden. */
  for (const spec of SCENES) {
    const row = rows.find((r) => r.position === spec.order);
    if (!row) continue;
    await prisma.scene.update({ where: { id: row.id }, data: { visualPrompt: spec.visualPrompt } });
  }
  console.log(`\nvisual prompts written to the six Scene rows (direct write: the scene PATCH has no visualPrompt field)`);

  const after = await scenes(pid);
  for (const s of after) {
    console.log(`  #${s.position} ${s.durationSeconds}s "${s.title}" | prompt: ${String(s.visualPrompt).slice(0, 90)}`);
  }
  writeFileSync(IDS_PATH, JSON.stringify({ projectId: pid, scenes: after.map((s) => ({ id: s.id, position: s.position })) }, null, 2));
  console.log(`\nproject id: ${pid}  (written to ${IDS_PATH})`);
  console.log(`PROJECT_ID=${pid}`);
}

/* ------------------------------------------------------------------- search */
interface Candidate extends Json {
  provider: string;
  externalId: string;
  title: string;
  author: string;
  width: number;
  height: number;
  durationSeconds?: number;
  pageUrl?: string;
  url: string;
}

interface SceneSearch {
  order: number;
  sceneId: string;
  title: string | null;
  visualPrompt: string | null;
  narration: string | null;
  query: string;
  subject: string[];
  status: number;
  providerStatus: string;
  candidates: Candidate[];
  providerResponses: unknown;
}

async function search(outPath: string) {
  const cookie = await signIn();
  const rows = await scenes();
  const all: SceneSearch[] = [];
  for (const s of rows) {
    const r = await call(cookie, `/api/media?sceneId=${s.id}&mediaType=video&count=${COUNT}`);
    if (r.status !== 200) throw new Error(`scene ${s.position}: media search answered ${r.status}: ${r.text.slice(0, 300)}`);
    const body = r.json as Json;
    const q = (body.query ?? {}) as Json;
    const list = (Array.isArray(body.candidates) ? body.candidates : []) as Candidate[];
    all.push({
      order: s.position,
      sceneId: s.id,
      title: s.title,
      visualPrompt: s.visualPrompt,
      narration: s.narration,
      query: String(q.keywords ?? ""),
      subject: (q.subject as string[]) ?? [],
      status: r.status,
      providerStatus: String(body.status ?? "?"),
      candidates: list,
      providerResponses: body.providerResponses ?? null,
    });
    console.log(`scene ${s.position}: ${r.status} ${String(body.status)} ${list.length} candidate(s) — query: ${String(q.keywords ?? "")}`);
    for (const c of list.slice(0, 10)) {
      console.log(
        `    ${c.provider}/${c.externalId}  ${c.width}x${c.height}  ${String(c.durationSeconds ?? "?")}s  ` +
          `${c.author}  — ${c.title}`,
      );
    }
  }
  writeFileSync(outPath, JSON.stringify({ base: BASE, project: projectId(), count: COUNT, scenes: all }, null, 2));
  console.log(`\nwritten to ${outPath}`);
}

/* ------------------------------------------------------------------- source */
async function source(order: number, externalId: string, inPath: string) {
  if (!existsSync(inPath)) throw new Error(`${inPath} not found — run the search step first`);
  const run = JSON.parse(readFileSync(inPath, "utf8")) as { scenes: SceneSearch[] };
  const scene = run.scenes.find((s) => s.order === order);
  if (!scene) throw new Error(`order ${order} is not in ${inPath}`);
  const chosen = scene.candidates.find((c) => String(c.externalId) === String(externalId));
  if (!chosen) {
    throw new Error(
      `provider/${externalId} was NOT in the candidate list the provider answered for scene ${order} ` +
        `(${scene.candidates.map((c) => c.externalId).join(", ") || "none"}) — refusing to select an asset that was never offered`,
    );
  }
  const cookie = await signIn();
  console.log(`scene ${order} (${scene.sceneId}) — query sent: ${scene.query}`);
  console.log(
    `chosen: ${chosen.provider}/${chosen.externalId} "${chosen.title}" by ${chosen.author} ` +
      `(${chosen.width}x${chosen.height}, ${chosen.durationSeconds ?? "?"}s)`,
  );

  const selected = await call(cookie, `/api/media/select`, {
    method: "POST",
    body: JSON.stringify({ sceneId: scene.sceneId, asset: chosen }),
  });
  if (selected.status !== 200 && selected.status !== 201) {
    throw new Error(`select answered ${selected.status}: ${selected.text.slice(0, 500)}`);
  }
  const selJson = selected.json as Json;
  const assetId = String((selJson.assetId as string) ?? ((selJson.asset as Json)?.id as string) ?? "");
  if (!assetId) throw new Error(`select answered ${selected.status} but no asset id: ${selected.text.slice(0, 400)}`);
  console.log(`select  → ${selected.status}  assetId ${assetId}`);

  const ingest = await call(cookie, `/api/media/ingest`, { method: "POST", body: JSON.stringify({ assetId }) });
  if (ingest.status !== 200) throw new Error(`ingest answered ${ingest.status}: ${ingest.text.slice(0, 800)}`);
  const ing = ingest.json as { footage: Json; alreadyStored: boolean };
  console.log(`ingest  → ${ingest.status}  alreadyStored=${ing.alreadyStored}`);
  console.log(`  storedKey : ${String(ing.footage.storedKey)}`);
  console.log(`  bytes     : ${String(ing.footage.bytes)}`);
  console.log(`  sha256    : ${String(ing.footage.sha256)}`);
  console.log(`  licence   : ${String(ing.footage.licenseType)} — ${String(ing.footage.licenseUrl)}`);
  console.log(`  pageUrl   : ${String(ing.footage.pageUrl)}`);
  console.log(`  author    : ${String(ing.footage.author)}`);
  console.log(`  scene ${order} now has ${await prisma.sceneAsset.count({ where: { sceneId: scene.sceneId } })} asset link(s)`);
}

/* ------------------------------------------------------------------- render */
async function render() {
  const cookie = await signIn();
  const pid = projectId();
  const rows = await scenes(pid);
  const declared = rows.reduce((n, s) => n + (s.durationSeconds ?? 0), 0);
  const links = await prisma.sceneAsset.groupBy({ by: ["sceneId"], where: { sceneId: { in: rows.map((r) => r.id) } }, _count: true });
  console.log(`project        : ${pid}`);
  console.log(`scenes         : ${rows.length}, declared total ${declared} s`);
  console.log(`scenes sourced : ${links.length} of ${rows.length}`);
  if (links.length !== rows.length) throw new Error(`only ${links.length} of ${rows.length} scenes have an asset link — the encode would refuse`);

  const enq = await call(cookie, `/api/studio/render`, {
    method: "POST",
    body: JSON.stringify({ action: "enqueue", projectId: pid, presetId: PRESET }),
  });
  if (enq.status !== 202) throw new Error(`enqueue answered ${enq.status}: ${enq.text.slice(0, 600)}`);
  const jobId = String((enq.json as Json).jobId);
  console.log(`\nRENDER JOB     : ${jobId}  (POST /api/studio/render → ${enq.status})`);
  console.log(`preset         : ${PRESET}`);

  const t0 = Date.now();
  let last = "";
  for (;;) {
    await new Promise((r) => setTimeout(r, 5000));
    const read = await call(cookie, `/api/studio/render?jobId=${jobId}`);
    if (read.status !== 200) throw new Error(`read answered ${read.status}: ${read.text.slice(0, 400)}`);
    const job = (read.json as { job: Json }).job;
    const status = String(job.status);
    const stages = (job.stages as Array<{ id: string; state: string }>) ?? [];
    const done = stages.filter((s) => s.state === "SUCCEEDED").length;
    const running = stages.find((s) => s.state === "RUNNING")?.id ?? "";
    const line = `${status} ${done}/${stages.length} ${running}`;
    if (line !== last) {
      console.log(`  ${((Date.now() - t0) / 1000).toFixed(0)}s  ${line}`);
      last = line;
    }
    if (["succeeded", "failed", "blocked", "stopped"].includes(status)) {
      console.log(`\nFINAL          : ${status} after ${((Date.now() - t0) / 1000).toFixed(0)}s`);
      writeFileSync("/tmp/p8demo_run.json", JSON.stringify({ projectId: pid, jobId, preset: PRESET, status, declared, job }, null, 2));
      console.log(`readout        : /tmp/p8demo_run.json`);
      console.log(`JOB_ID=${jobId}`);
      if (status !== "succeeded") process.exit(3);
      break;
    }
    if (Date.now() - t0 > 90 * 60 * 1000) throw new Error("render did not finish within 90 minutes");
  }
}

/* -------------------------------------------------------------------- table */
async function table(inPath: string, outPath: string) {
  const run = existsSync(inPath) ? (JSON.parse(readFileSync(inPath, "utf8")) as { scenes: SceneSearch[] }) : { scenes: [] };
  const rows = await scenes();
  const lines: string[] = [];
  lines.push("| # | scene | query sent to the provider | provider id | author | page URL | stored key | bytes | sha256 | licence |");
  lines.push("|---|-------|---------------------------|-------------|--------|----------|-----------|-------|--------|---------|");
  for (const s of rows) {
    const searched = run.scenes.find((x) => x.sceneId === s.id);
    const links = await prisma.sceneAsset.findMany({
      where: { sceneId: s.id },
      orderBy: { order: "asc" },
      select: {
        asset: {
          select: {
            id: true,
            s3Key: true,
            sizeBytes: true,
            metadata: true,
            stockAsset: { select: { provider: true, externalId: true, pageUrl: true } },
            licensing: { select: { licenseType: true, licenseUrl: true, source: true, attribution: true } },
          },
        },
      },
    });
    const a = links[0]?.asset;
    const f = ((a?.metadata as Json | null)?.footage ?? null) as Json | null;
    lines.push(
      `| ${s.position} | ${s.title ?? ""} | ${searched?.query ?? "(no search recorded)"} | ${
        a?.stockAsset ? `${a.stockAsset.provider}/${a.stockAsset.externalId}` : "—"
      } | ${f ? String(f.author ?? "—") : "—"} | ${a?.stockAsset?.pageUrl ?? "—"} | ${a?.s3Key ?? "—"} | ${
        a?.sizeBytes ? String(a.sizeBytes) : "—"
      } | ${f ? String(f.sha256 ?? "—") : "—"} | ${a?.licensing ? String(a.licensing.licenseType) : "—"} |`,
    );
  }
  const text = lines.join("\n");
  writeFileSync(outPath, text + "\n");
  console.log(text);
  console.log(`\nwritten to ${outPath}`);
}

const [mode, a1, a2, a3] = process.argv.slice(2);
if (mode === "create") await create();
else if (mode === "search") await search(a1 ?? "/tmp/p8demo_candidates.json");
else if (mode === "source") await source(Number(a1), String(a2), a3 ?? "/tmp/p8demo_candidates.json");
else if (mode === "render") await render();
else if (mode === "table") await table(a1 ?? "/tmp/p8demo_candidates.json", a2 ?? "/tmp/p8demo_table.md");
else {
  console.error("usage: create | search [out.json] | source <order> <externalId> [in.json] | render | table [in.json] [out.md]");
  process.exit(2);
}
process.exit(0);
